template<class... Expressions>
	requires (sizeof...(Expressions) != 0 && (::vkfu::expression_for<Expressions, ::vkfu::obj::compute_pipeline> && ...))
[[nodiscard]] auto create_compute_pipelines(VkDevice device, VkPipelineCache pipelineCache, ::VkAllocationCallbacks const* allocation_callbacks,
	::std::nothrow_t, Expressions&&... infos) noexcept
	-> ::std::expected<::std::array<VkPipeline, sizeof...(Expressions)>, ::VkResult>
{
	auto storages = ::std::tuple{::vkfu::evaluate(::std::forward<Expressions>(infos))...};
	auto const natives = [&]<::std::size_t... Indices>(::std::index_sequence<Indices...>)
	{
		return ::std::array<VkComputePipelineCreateInfo, sizeof...(Expressions)>{::vkfu::unpack(::std::get<Indices>(storages))...};
	}(::std::index_sequence_for<Expressions...>{});
	auto produced = ::std::array<VkPipeline, sizeof...(Expressions)>{};
	auto const result = ::vkCreateComputePipelines(
		device, pipelineCache, static_cast<::std::uint32_t>(natives.size()), natives.data(),
		allocation_callbacks, produced.data());
	if (result != ::VK_SUCCESS)
	{
		return ::std::unexpected{result};
	}
	return produced;
}

template<class... Expressions>
	requires (sizeof...(Expressions) != 0 && (::vkfu::expression_for<Expressions, ::vkfu::obj::compute_pipeline> && ...))
[[nodiscard]] auto create_compute_pipelines(VkDevice device, VkPipelineCache pipelineCache, ::VkAllocationCallbacks const* allocation_callbacks,
	Expressions&&... infos) -> ::std::array<VkPipeline, sizeof...(Expressions)>
{
	auto produced = create_compute_pipelines(device, pipelineCache, allocation_callbacks, ::std::nothrow, ::std::forward<Expressions>(infos)...);
	if (!produced)
	{
		throw produced.error();
	}
	return *produced;
}

// One structure is the common case, and reads better than a one-element array.
template<::vkfu::expression_for<::vkfu::obj::compute_pipeline> Expression>
[[nodiscard]] auto create_compute_pipeline(VkDevice device, VkPipelineCache pipelineCache, Expression&& info, ::VkAllocationCallbacks const* allocation_callbacks = nullptr)
	-> VkPipeline
{
	return create_compute_pipelines(device, pipelineCache, allocation_callbacks, ::std::forward<Expression>(info))[0];
}

template<::vkfu::expression_for<::vkfu::obj::compute_pipeline> Expression>
[[nodiscard]] auto create_compute_pipeline(VkDevice device, VkPipelineCache pipelineCache, Expression&& info, ::VkAllocationCallbacks const* allocation_callbacks, ::std::nothrow_t) noexcept
	-> ::std::expected<VkPipeline, ::VkResult>
{
	auto produced = create_compute_pipelines(device, pipelineCache, allocation_callbacks, ::std::nothrow, ::std::forward<Expression>(info));
	if (!produced)
	{
		return ::std::unexpected{produced.error()};
	}
	return (*produced)[0];
}

